import * as THREE from 'three'

function rng(seed) {
  let s = seed >>> 0
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0
    return s / 4294967296
  }
}

function canvasTexture(size, paint, { repeat = [1, 1], srgb = true } = {}) {
  const canvas = document.createElement('canvas')
  canvas.width = size
  canvas.height = size
  const ctx = canvas.getContext('2d')
  paint(ctx, size)
  const tex = new THREE.CanvasTexture(canvas)
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping
  tex.repeat.set(repeat[0], repeat[1])
  tex.anisotropy = 4
  if (srgb) tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

function noise(ctx, size, amount, alpha = 0.1, light = false) {
  const rand = rng(size * 97 + amount * 13)
  for (let i = 0; i < amount; i++) {
    const x = rand() * size
    const y = rand() * size
    const r = rand() * 2 + 0.4
    const value = light ? 210 + rand() * 45 : 5 + rand() * 30
    ctx.fillStyle = `rgba(${value},${value},${value},${alpha * rand()})`
    ctx.beginPath()
    ctx.arc(x, y, r, 0, Math.PI * 2)
    ctx.fill()
  }
}

function stains(ctx, size, count, color = '45,34,20') {
  const rand = rng(size * 31 + count)
  for (let i = 0; i < count; i++) {
    const x = rand() * size
    const y = rand() * size
    const r = 10 + rand() * 45
    const g = ctx.createRadialGradient(x, y, r * 0.05, x, y, r)
    g.addColorStop(0, `rgba(${color},${0.16 + rand() * 0.16})`)
    g.addColorStop(0.55, `rgba(${color},0.06)`)
    g.addColorStop(1, `rgba(${color},0)`)
    ctx.fillStyle = g
    ctx.beginPath()
    ctx.ellipse(x, y, r, r * (0.5 + rand() * 0.8), rand() * Math.PI, 0, Math.PI * 2)
    ctx.fill()
  }
}

export function woodFloorTexture() {
  return canvasTexture(512, (ctx, s) => {
    const rand = rng(451)
    ctx.fillStyle = '#2e2118'
    ctx.fillRect(0, 0, s, s)
    for (let row = 0; row < 8; row++) {
      const y = row * 64
      const shade = 36 + Math.floor(rand() * 15)
      ctx.fillStyle = `rgb(${shade + 16},${shade + 2},${Math.max(12, shade - 14)})`
      ctx.fillRect(0, y + 1, s, 62)
      ctx.strokeStyle = 'rgba(8,5,3,.8)'
      ctx.lineWidth = 2
      ctx.beginPath()
      ctx.moveTo(0, y)
      ctx.lineTo(s, y)
      ctx.stroke()
      for (let g = 0; g < 18; g++) {
        ctx.strokeStyle = `rgba(15,8,4,${0.03 + rand() * 0.08})`
        ctx.lineWidth = 0.7 + rand()
        const gy = y + 5 + rand() * 52
        ctx.beginPath()
        ctx.moveTo(0, gy)
        for (let x = 0; x <= s; x += 32) ctx.lineTo(x, gy + Math.sin(x * 0.03 + g) * 2)
        ctx.stroke()
      }
      const joint = Math.floor(rand() * s)
      ctx.fillStyle = 'rgba(6,4,2,.7)'
      ctx.fillRect(joint, y, 3, 64)
      if (rand() > 0.65) {
        ctx.strokeStyle = 'rgba(15,10,6,.3)'
        ctx.beginPath()
        ctx.ellipse(rand() * s, y + 35, 21, 4, 0, 0, Math.PI * 2)
        ctx.stroke()
      }
    }
    stains(ctx, s, 24, '15,8,4')
    noise(ctx, s, 800, 0.06)
  }, { repeat: [4, 4] })
}

export function wallpaperTexture(base = '#42473a', motif = '#5e6451') {
  return canvasTexture(256, (ctx, s) => {
    const rand = rng(s + 71)
    ctx.fillStyle = base
    ctx.fillRect(0, 0, s, s)
    ctx.fillStyle = 'rgba(255,244,210,.025)'
    for (let x = 0; x < s; x += 32) ctx.fillRect(x, 0, 1, s)
    ctx.strokeStyle = motif
    ctx.globalAlpha = 0.38
    for (let x = 16; x < s; x += 64) {
      for (let y = 18; y < s; y += 64) {
        ctx.beginPath()
        ctx.ellipse(x, y, 9, 17, 0, 0, Math.PI * 2)
        ctx.stroke()
        ctx.beginPath()
        ctx.arc(x, y - 11, 4, 0, Math.PI * 2)
        ctx.stroke()
        ctx.beginPath()
        ctx.moveTo(x - 10, y + 18)
        ctx.quadraticCurveTo(x, y + 30, x + 10, y + 18)
        ctx.stroke()
      }
    }
    ctx.globalAlpha = 1
    for (let i = 0; i < 7; i++) {
      const x = rand() * s
      const y = rand() * s
      ctx.fillStyle = `rgba(38,29,15,${0.1 + rand() * 0.12})`
      ctx.beginPath()
      ctx.ellipse(x, y, 20 + rand() * 45, 9 + rand() * 45, rand() * 3, 0, Math.PI * 2)
      ctx.fill()
    }
    noise(ctx, s, 1300, 0.065)
  }, { repeat: [2.4, 1.4] })
}

export function plasterTexture() {
  return canvasTexture(256, (ctx, s) => {
    const rand = rng(139)
    ctx.fillStyle = '#5a5548'
    ctx.fillRect(0, 0, s, s)
    for (let i = 0; i < 60; i++) {
      ctx.fillStyle = `rgba(${25 + rand() * 50},${25 + rand() * 48},${20 + rand() * 38},${0.08 + rand() * 0.08})`
      ctx.fillRect(rand() * s, rand() * s, 10 + rand() * 60, 6 + rand() * 40)
    }
    stains(ctx, s, 12, '38,30,18')
    noise(ctx, s, 1000, 0.08)
  }, { repeat: [2, 1.4] })
}

export function concreteTexture() {
  return canvasTexture(256, (ctx, s) => {
    const rand = rng(777)
    ctx.fillStyle = '#3f4241'
    ctx.fillRect(0, 0, s, s)
    for (let i = 0; i < 900; i++) {
      const v = 40 + rand() * 50
      ctx.fillStyle = `rgba(${v},${v + 2},${v},${0.12 + rand() * 0.2})`
      ctx.fillRect(rand() * s, rand() * s, 1 + rand() * 4, 1 + rand() * 4)
    }
    stains(ctx, s, 18, '14,18,14')
    for (let i = 0; i < 8; i++) {
      ctx.strokeStyle = `rgba(15,17,16,${0.2 + rand() * 0.3})`
      ctx.beginPath()
      let x = rand() * s
      let y = rand() * s
      ctx.moveTo(x, y)
      for (let j = 0; j < 6; j++) {
        x += (rand() - 0.5) * 40
        y += rand() * 22
        ctx.lineTo(x, y)
      }
      ctx.stroke()
    }
  }, { repeat: [3, 3] })
}

export function woodTexture(base = '#3a2618') {
  return canvasTexture(256, (ctx, s) => {
    const rand = rng(88)
    ctx.fillStyle = base
    ctx.fillRect(0, 0, s, s)
    for (let i = 0; i < 130; i++) {
      const y = rand() * s
      ctx.strokeStyle = `rgba(${8 + rand() * 18},${5 + rand() * 12},${2 + rand() * 8},${0.08 + rand() * 0.18})`
      ctx.lineWidth = 0.5 + rand() * 2
      ctx.beginPath()
      ctx.moveTo(0, y)
      for (let x = 0; x <= s; x += 20) ctx.lineTo(x, y + Math.sin(x * 0.02 + i) * 3)
      ctx.stroke()
    }
    stains(ctx, s, 8, '10,6,3')
    noise(ctx, s, 260, 0.07)
  }, { repeat: [1, 1] })
}

export function ceilingTexture() {
  return canvasTexture(256, (ctx, s) => {
    const rand = rng(191)
    ctx.fillStyle = '#37352d'
    ctx.fillRect(0, 0, s, s)
    stains(ctx, s, 20, '25,22,16')
    for (let i = 0; i < 15; i++) {
      ctx.strokeStyle = `rgba(20,18,13,${0.18 + rand() * 0.25})`
      ctx.beginPath()
      const x = rand() * s
      const y = rand() * s
      ctx.moveTo(x, y)
      ctx.lineTo(x + (rand() - 0.5) * 80, y + rand() * 50)
      ctx.stroke()
    }
    noise(ctx, s, 700, 0.08)
  }, { repeat: [2, 2] })
}

export function tileTexture() {
  return canvasTexture(256, (ctx, s) => {
    const rand = rng(421)
    ctx.fillStyle = '#5a5c4f'
    ctx.fillRect(0, 0, s, s)
    for (let y = 0; y < s; y += 32) {
      for (let x = 0; x < s; x += 32) {
        const v = 78 + rand() * 26
        ctx.fillStyle = `rgba(${v},${v + 4},${v - 3},${0.5})`
        ctx.fillRect(x + 1, y + 1, 30, 30)
      }
    }
    ctx.strokeStyle = 'rgba(20,22,17,.7)'
    ctx.lineWidth = 2
    for (let i = 0; i <= s; i += 32) {
      ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, s); ctx.stroke()
      ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(s, i); ctx.stroke()
    }
    stains(ctx, s, 14, '25,23,14')
    noise(ctx, s, 500, 0.06)
  }, { repeat: [3, 2] })
}

export function rugTexture() {
  return canvasTexture(512, (ctx, s) => {
    const rand = rng(1948)
    ctx.fillStyle = '#4b1f1b'
    ctx.fillRect(0, 0, s, s)
    ctx.strokeStyle = '#80604b'
    ctx.lineWidth = 5
    ctx.strokeRect(18, 18, s - 36, s - 36)
    ctx.strokeStyle = 'rgba(180,151,113,.4)'
    ctx.lineWidth = 2
    ctx.strokeRect(35, 35, s - 70, s - 70)
    for (let i = 0; i < 9; i++) {
      for (let j = 0; j < 9; j++) {
        const x = 60 + i * 45
        const y = 60 + j * 45
        ctx.save()
        ctx.translate(x, y)
        ctx.rotate(Math.PI / 4)
        ctx.strokeStyle = 'rgba(126,87,62,.35)'
        ctx.strokeRect(-12, -12, 24, 24)
        ctx.restore()
      }
    }
    stains(ctx, s, 22, '18,8,5')
    noise(ctx, s, 1900, 0.06)
  })
}

export function portraitTexture() {
  return canvasTexture(256, (ctx, s) => {
    const rand = rng(1912)
    const g = ctx.createLinearGradient(0, 0, 0, s)
    g.addColorStop(0, '#6b5b44')
    g.addColorStop(1, '#2a2119')
    ctx.fillStyle = g
    ctx.fillRect(0, 0, s, s)
    ctx.fillStyle = 'rgba(29,21,16,.85)'
    ctx.beginPath()
    ctx.ellipse(s / 2, 66, 32, 38, 0, 0, Math.PI * 2)
    ctx.fill()
    ctx.beginPath()
    ctx.moveTo(60, s)
    ctx.quadraticCurveTo(64, 130, 112, 115)
    ctx.lineTo(144, 115)
    ctx.quadraticCurveTo(192, 130, 196, s)
    ctx.closePath()
    ctx.fill()
    ctx.fillStyle = 'rgba(213,188,146,.7)'
    ctx.beginPath()
    ctx.ellipse(s / 2, 69, 24, 30, 0, 0, Math.PI * 2)
    ctx.fill()
    ctx.fillStyle = 'rgba(24,17,13,.95)'
    ctx.beginPath(); ctx.ellipse(117, 65, 4, 5, 0, 0, Math.PI * 2); ctx.fill()
    ctx.beginPath(); ctx.ellipse(139, 65, 4, 5, 0, 0, Math.PI * 2); ctx.fill()
    ctx.beginPath(); ctx.arc(128, 82, 7, 0, Math.PI); ctx.fill()
    for (let i = 0; i < 45; i++) {
      const x = rand() * s
      const y = rand() * s
      ctx.fillStyle = `rgba(20,15,10,${0.1 + rand() * 0.3})`
      ctx.fillRect(x, y, 1 + rand() * 8, 1 + rand() * 2)
    }
    ctx.strokeStyle = 'rgba(20,14,10,.5)'
    ctx.lineWidth = 2
    ctx.beginPath(); ctx.moveTo(60, 220); ctx.lineTo(80, 40); ctx.stroke()
  })
}

export function windowTexture() {
  return canvasTexture(256, (ctx, s) => {
    const rand = rng(301)
    const g = ctx.createLinearGradient(0, 0, 0, s)
    g.addColorStop(0, '#263342')
    g.addColorStop(0.55, '#11181e')
    g.addColorStop(1, '#070a0b')
    ctx.fillStyle = g
    ctx.fillRect(0, 0, s, s)
    ctx.strokeStyle = 'rgba(166,191,204,.12)'
    ctx.lineWidth = 1
    for (let i = 0; i < 80; i++) {
      const x = rand() * s
      const y = rand() * s
      ctx.beginPath()
      ctx.moveTo(x, y)
      ctx.lineTo(x - 4, y + 14 + rand() * 18)
      ctx.stroke()
    }
    ctx.fillStyle = 'rgba(3,5,6,.8)'
    ctx.beginPath()
    ctx.moveTo(0, 190)
    ctx.lineTo(40, 155)
    ctx.lineTo(58, 190)
    ctx.lineTo(90, 168)
    ctx.lineTo(120, 195)
    ctx.lineTo(150, 160)
    ctx.lineTo(190, 193)
    ctx.lineTo(256, 170)
    ctx.lineTo(256, 256)
    ctx.lineTo(0, 256)
    ctx.closePath()
    ctx.fill()
  })
}

export function noteTexture() {
  return canvasTexture(256, (ctx, s) => {
    const rand = rng(617)
    ctx.fillStyle = '#c6b992'
    ctx.fillRect(0, 0, s, s)
    ctx.fillStyle = 'rgba(66,50,30,.8)'
    ctx.font = '20px Georgia'
    ctx.fillText('IF YOU READ THIS', 24, 42)
    ctx.font = '13px Georgia'
    const lines = ['the generator is dead.', 'two fuses are missing.', '', 'do not go down there.', 'it knows when the lights', 'come on.']
    lines.forEach((line, i) => ctx.fillText(line, 25, 76 + i * 22))
    for (let i = 0; i < 70; i++) {
      ctx.fillStyle = `rgba(70,52,28,${rand() * 0.11})`
      ctx.fillRect(rand() * s, rand() * s, 1 + rand() * 9, 1 + rand() * 3)
    }
    ctx.strokeStyle = 'rgba(85,60,30,.2)'
    ctx.strokeRect(3, 3, s - 6, s - 6)
  })
}

export function bloodTexture() {
  return canvasTexture(256, (ctx, s) => {
    const rand = rng(66)
    ctx.clearRect(0, 0, s, s)
    const g = ctx.createRadialGradient(128, 128, 4, 128, 128, 100)
    g.addColorStop(0, 'rgba(74,10,7,.9)')
    g.addColorStop(0.5, 'rgba(48,5,4,.65)')
    g.addColorStop(1, 'rgba(21,2,2,0)')
    ctx.fillStyle = g
    ctx.beginPath()
    ctx.arc(128, 128, 100, 0, Math.PI * 2)
    ctx.fill()
    for (let i = 0; i < 35; i++) {
      const a = rand() * Math.PI * 2
      const d = 60 + rand() * 80
      ctx.fillStyle = `rgba(58,7,5,${0.3 + rand() * 0.5})`
      ctx.beginPath()
      ctx.arc(128 + Math.cos(a) * d, 128 + Math.sin(a) * d, 1 + rand() * 6, 0, Math.PI * 2)
      ctx.fill()
    }
  })
}

export function maskTexture() {
  return canvasTexture(256, (ctx, s) => {
    ctx.clearRect(0, 0, s, s)
    ctx.fillStyle = '#c9bea7'
    ctx.beginPath()
    ctx.ellipse(128, 136, 75, 106, 0, 0, Math.PI * 2)
    ctx.fill()
    ctx.fillStyle = '#17130f'
    ctx.beginPath(); ctx.ellipse(99, 118, 16, 12, -0.1, 0, Math.PI * 2); ctx.fill()
    ctx.beginPath(); ctx.ellipse(157, 118, 16, 12, 0.1, 0, Math.PI * 2); ctx.fill()
    ctx.strokeStyle = '#544737'
    ctx.lineWidth = 3
    ctx.beginPath()
    for (let x = 88; x <= 168; x += 10) {
      ctx.moveTo(x, 180)
      ctx.lineTo(x + 4, 196)
    }
    ctx.stroke()
    ctx.strokeStyle = 'rgba(50,37,25,.4)'
    ctx.lineWidth = 1.5
    ctx.beginPath()
    ctx.moveTo(128, 190); ctx.lineTo(122, 230)
    ctx.moveTo(128, 150); ctx.lineTo(132, 172)
    ctx.stroke()
  })
}

export function glowTexture() {
  return canvasTexture(128, (ctx, s) => {
    const g = ctx.createRadialGradient(64, 64, 0, 64, 64, 62)
    g.addColorStop(0, 'rgba(255,220,160,.95)')
    g.addColorStop(0.2, 'rgba(255,190,100,.55)')
    g.addColorStop(0.6, 'rgba(200,120,40,.12)')
    g.addColorStop(1, 'rgba(0,0,0,0)')
    ctx.fillStyle = g
    ctx.fillRect(0, 0, s, s)
  })
}

export function paperTexture() {
  return canvasTexture(128, (ctx, s) => {
    const rand = rng(70)
    ctx.fillStyle = '#c3b58e'
    ctx.fillRect(0, 0, s, s)
    for (let i = 0; i < 15; i++) {
      ctx.fillStyle = `rgba(90,70,40,${0.05 + rand() * 0.1})`
      ctx.fillRect(0, rand() * s, s, 1)
    }
  })
}

export class Soundscape {
  constructor() {
    this.ctx = null
    this.master = null
    this.started = false
    this.creakTimer = 8
    this.heartTimer = 0
    this.danger = 0
    this.enemyGain = null
    this.muted = false
  }

  init() {
    if (this.started) return
    const Ctx = window.AudioContext || window.webkitAudioContext
    if (!Ctx) return
    this.ctx = new Ctx()
    const ctx = this.ctx
    this.master = ctx.createGain()
    this.master.gain.value = 0.62
    const compressor = ctx.createDynamicsCompressor()
    compressor.threshold.value = -22
    compressor.knee.value = 18
    compressor.ratio.value = 5
    compressor.attack.value = 0.005
    compressor.release.value = 0.35
    this.master.connect(compressor)
    compressor.connect(ctx.destination)
    this.started = true

    this.noiseBuffer = this.makeNoise(2.2, 'brown')
    this.whiteBuffer = this.makeNoise(1.2, 'white')

    this.startAmbient()
  }

  makeNoise(seconds, color = 'white') {
    const ctx = this.ctx
    const buffer = ctx.createBuffer(2, Math.floor(ctx.sampleRate * seconds), ctx.sampleRate)
    for (let channel = 0; channel < 2; channel++) {
      const data = buffer.getChannelData(channel)
      let last = 0
      for (let i = 0; i < data.length; i++) {
        const white = Math.random() * 2 - 1
        if (color === 'brown') {
          last = (last + 0.018 * white) / 1.018
          data[i] = last * 3.2
        } else {
          data[i] = white * 0.7
        }
      }
    }
    return buffer
  }

  loopNoise(volume, type, frequency, q = 1) {
    const ctx = this.ctx
    const src = ctx.createBufferSource()
    src.buffer = this.noiseBuffer
    src.loop = true
    const filter = ctx.createBiquadFilter()
    filter.type = type
    filter.frequency.value = frequency
    filter.Q.value = q
    const gain = ctx.createGain()
    gain.gain.value = volume
    src.connect(filter)
    filter.connect(gain)
    gain.connect(this.master)
    src.start()
    return { src, gain, filter }
  }

  startAmbient() {
    const ctx = this.ctx
    this.rain = this.loopNoise(0.045, 'highpass', 950)
    this.wind = this.loopNoise(0.045, 'bandpass', 420, 0.6)
    const lfo = ctx.createOscillator()
    const lfoGain = ctx.createGain()
    lfo.frequency.value = 0.055
    lfoGain.gain.value = 170
    lfo.connect(lfoGain)
    lfoGain.connect(this.wind.filter.frequency)
    lfo.start()

    const droneGain = ctx.createGain()
    droneGain.gain.value = 0.033
    droneGain.connect(this.master)
    for (const [freq, detune] of [[43, 0], [55.5, 7], [82, -5]]) {
      const osc = ctx.createOscillator()
      osc.type = 'sawtooth'
      osc.frequency.value = freq
      osc.detune.value = detune
      const filter = ctx.createBiquadFilter()
      filter.type = 'lowpass'
      filter.frequency.value = 160
      filter.Q.value = 2
      const gain = ctx.createGain()
      gain.gain.value = 0.26
      osc.connect(filter)
      filter.connect(gain)
      gain.connect(droneGain)
      osc.start()
    }

    this.enemyGrowlGain = ctx.createGain()
    this.enemyGrowlGain.gain.value = 0
    this.enemyGrowlGain.connect(this.master)
    const growl = ctx.createBufferSource()
    growl.buffer = this.noiseBuffer
    growl.loop = true
    const growlFilter = ctx.createBiquadFilter()
    growlFilter.type = 'lowpass'
    growlFilter.frequency.value = 190
    growlFilter.Q.value = 2.5
    const growlOsc = ctx.createOscillator()
    growlOsc.type = 'sawtooth'
    growlOsc.frequency.value = 47
    const oscGain = ctx.createGain()
    oscGain.gain.value = 0.15
    growl.connect(growlFilter)
    growlFilter.connect(this.enemyGrowlGain)
    growlOsc.connect(oscGain)
    oscGain.connect(this.enemyGrowlGain)
    growl.start()
    growlOsc.start()
    this.enemyGrowlOsc = growlOsc
  }

  setMuted(value) {
    if (!this.ctx) return
    this.muted = value
    this.master.gain.setTargetAtTime(value ? 0 : 0.62, this.ctx.currentTime, 0.08)
  }

  pulse(duration, frequency, volume, type = 'sine') {
    if (!this.ctx) return
    const now = this.ctx.currentTime
    const osc = this.ctx.createOscillator()
    const gain = this.ctx.createGain()
    osc.type = type
    osc.frequency.value = frequency
    gain.gain.setValueAtTime(0.0001, now)
    gain.gain.exponentialRampToValueAtTime(volume, now + 0.008)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration)
    osc.connect(gain)
    gain.connect(this.master)
    osc.start(now)
    osc.stop(now + duration + 0.02)
  }

  noiseBurst(duration, frequency, volume, type = 'lowpass', q = 1) {
    if (!this.ctx) return
    const now = this.ctx.currentTime
    const src = this.ctx.createBufferSource()
    src.buffer = this.whiteBuffer
    const filter = this.ctx.createBiquadFilter()
    filter.type = type
    filter.frequency.value = frequency
    filter.Q.value = q
    const gain = this.ctx.createGain()
    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration)
    src.connect(filter)
    filter.connect(gain)
    gain.connect(this.master)
    src.start(now)
    src.stop(now + duration + 0.05)
  }

  click() {
    this.pulse(0.04, 880, 0.035, 'triangle')
  }

  pickup() {
    if (!this.ctx) return
    this.pulse(0.25, 420, 0.06, 'sine')
    setTimeout(() => this.pulse(0.4, 640, 0.045, 'sine'), 80)
    this.noiseBurst(0.12, 2600, 0.025, 'bandpass', 1.5)
  }

  deny() {
    this.pulse(0.12, 105, 0.09, 'square')
    this.pulse(0.18, 78, 0.07, 'sawtooth')
  }

  door() {
    this.noiseBurst(0.9, 430, 0.07, 'bandpass', 4)
    if (!this.ctx) return
    const now = this.ctx.currentTime
    const osc = this.ctx.createOscillator()
    const gain = this.ctx.createGain()
    osc.type = 'sawtooth'
    osc.frequency.setValueAtTime(68, now)
    osc.frequency.exponentialRampToValueAtTime(37, now + 1.1)
    gain.gain.setValueAtTime(0.0001, now)
    gain.gain.exponentialRampToValueAtTime(0.035, now + 0.15)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 1.2)
    osc.connect(gain)
    gain.connect(this.master)
    osc.start()
    osc.stop(now + 1.3)
  }

  power() {
    if (!this.ctx) return
    this.noiseBurst(0.4, 1800, 0.09, 'highpass')
    this.pulse(0.7, 52, 0.13, 'sawtooth')
    setTimeout(() => this.noiseBurst(3.3, 120, 0.02, 'bandpass', 1.2), 220)
  }

  gunshot() {
    if (!this.ctx) return
    const now = this.ctx.currentTime
    this.noiseBurst(0.36, 1500, 0.42, 'lowpass')
    this.noiseBurst(0.16, 3800, 0.16, 'highpass')
    const osc = this.ctx.createOscillator()
    const gain = this.ctx.createGain()
    osc.frequency.setValueAtTime(140, now)
    osc.frequency.exponentialRampToValueAtTime(44, now + 0.28)
    gain.gain.setValueAtTime(0.28, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.32)
    osc.connect(gain)
    gain.connect(this.master)
    osc.start()
    osc.stop(now + 0.34)
  }

  reload() {
    this.noiseBurst(0.06, 2300, 0.05, 'bandpass', 2)
    setTimeout(() => this.noiseBurst(0.08, 1400, 0.05, 'bandpass', 3), 230)
    setTimeout(() => this.noiseBurst(0.05, 2800, 0.06, 'bandpass', 2), 620)
  }

  empty() {
    this.noiseBurst(0.04, 2800, 0.045, 'bandpass', 3)
  }

  step(concrete = false) {
    if (!this.ctx) return
    this.noiseBurst(0.13, concrete ? 380 : 220, 0.055, 'lowpass')
    this.noiseBurst(0.06, concrete ? 1700 : 850, 0.018, 'bandpass', 1.4)
  }

  heartbeat(strength = 0.5) {
    if (!this.ctx) return
    const now = this.ctx.currentTime
    for (const [delay, vol] of [[0, 0.025 + strength * 0.06], [0.18, 0.014 + strength * 0.03]]) {
      const osc = this.ctx.createOscillator()
      const gain = this.ctx.createGain()
      osc.type = 'sine'
      osc.frequency.setValueAtTime(72, now + delay)
      osc.frequency.exponentialRampToValueAtTime(36, now + delay + 0.16)
      gain.gain.setValueAtTime(vol, now + delay)
      gain.gain.exponentialRampToValueAtTime(0.0001, now + delay + 0.2)
      osc.connect(gain)
      gain.connect(this.master)
      osc.start(now + delay)
      osc.stop(now + delay + 0.22)
    }
  }

  stinger() {
    if (!this.ctx) return
    this.noiseBurst(1.8, 560, 0.2, 'bandpass', 1.1)
    this.pulse(2.2, 38, 0.17, 'sawtooth')
    const now = this.ctx.currentTime
    const osc = this.ctx.createOscillator()
    const gain = this.ctx.createGain()
    osc.type = 'sawtooth'
    osc.frequency.setValueAtTime(360, now)
    osc.frequency.exponentialRampToValueAtTime(42, now + 1.4)
    gain.gain.setValueAtTime(0.0001, now)
    gain.gain.exponentialRampToValueAtTime(0.11, now + 0.05)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 1.6)
    osc.connect(gain)
    gain.connect(this.master)
    osc.start()
    osc.stop(now + 1.7)
  }

  enemyHit() {
    this.noiseBurst(0.18, 320, 0.17, 'lowpass')
    this.pulse(0.24, 66, 0.12, 'sawtooth')
  }

  playerHit() {
    this.noiseBurst(0.32, 260, 0.2, 'lowpass')
    this.pulse(0.4, 47, 0.16, 'sawtooth')
  }

  death() {
    if (!this.ctx) return
    this.noiseBurst(2.4, 340, 0.2, 'lowpass')
    this.pulse(3.4, 30, 0.2, 'sawtooth')
  }

  victory() {
    if (!this.ctx) return
    const notes = [196, 246.94, 293.66, 392]
    notes.forEach((freq, i) => {
      setTimeout(() => {
        this.pulse(2.8, freq, 0.035, 'sine')
        this.pulse(2.8, freq * 2, 0.012, 'triangle')
      }, i * 260)
    })
  }

  creak() {
    if (!this.ctx) return
    const now = this.ctx.currentTime
    const osc = this.ctx.createOscillator()
    const gain = this.ctx.createGain()
    osc.type = 'sawtooth'
    osc.frequency.setValueAtTime(85 + Math.random() * 70, now)
    osc.frequency.linearRampToValueAtTime(45 + Math.random() * 40, now + 1.4)
    gain.gain.setValueAtTime(0.0001, now)
    gain.gain.exponentialRampToValueAtTime(0.022, now + 0.2)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 1.6)
    osc.connect(gain)
    gain.connect(this.master)
    osc.start()
    osc.stop(now + 1.7)
    this.noiseBurst(0.7, 900, 0.012, 'bandpass', 4)
  }

  update(dt, danger) {
    if (!this.ctx) return
    this.danger += (danger - this.danger) * Math.min(1, dt * 2)
    this.heartTimer -= dt
    if (this.danger > 0.16 && this.heartTimer <= 0) {
      this.heartbeat(Math.min(1, this.danger))
      this.heartTimer = 1.25 - this.danger * 0.65
    }
    if (this.enemyGrowlGain) {
      const target = this.danger > 0.05 ? Math.min(0.13, 0.02 + this.danger * 0.13) : 0
      this.enemyGrowlGain.gain.setTargetAtTime(target, this.ctx.currentTime, 0.25)
    }
    if (this.enemyGrowlOsc) {
      this.enemyGrowlOsc.frequency.setTargetAtTime(44 + Math.sin(performance.now() * 0.001) * 3, this.ctx.currentTime, 0.2)
    }
    this.creakTimer -= dt
    if (this.creakTimer <= 0) {
      this.creak()
      this.creakTimer = 13 + Math.random() * 18
    }
  }
}

@font-face {
  font-family: 'Bodoni Moda';
  src: url('./fonts/bodoni-moda.woff2') format('woff2');
  font-weight: 400 700;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Barlow Condensed';
  src: url('./fonts/barlow-condensed-300.woff2') format('woff2');
  font-weight: 300;
  font-display: swap;
}
@font-face {
  font-family: 'Barlow Condensed';
  src: url('./fonts/barlow-condensed-400.woff2') format('woff2');
  font-weight: 400;
  font-display: swap;
}
@font-face {
  font-family: 'Barlow Condensed';
  src: url('./fonts/barlow-condensed-500.woff2') format('woff2');
  font-weight: 500;
  font-display: swap;
}

:root {
  --ink: #050605;
  --bone: #d8cdb8;
  --bone-dim: #998f7d;
  --blood: #9b2f23;
  --blood-bright: #c04431;
  --moss: #74806a;
  --line: rgba(216, 205, 184, .22);
  --serif: 'Bodoni Moda', 'Times New Roman', serif;
  --cond: 'Barlow Condensed', 'Arial Narrow', sans-serif;
}

* { box-sizing: border-box; }
html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--bone);
  font-family: var(--cond);
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}
body {
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}
button { font: inherit; color: inherit; }
button:focus-visible { outline: 1px solid var(--bone); outline-offset: 4px; }

#app { position: fixed; inset: 0; background: #000; isolation: isolate; }
#scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  cursor: crosshair;
  touch-action: none;
}

.grade {
  position: absolute; inset: 0; pointer-events: none; z-index: 2;
  background:
    radial-gradient(ellipse at 65% 38%, rgba(90, 102, 83, .045), transparent 45%),
    linear-gradient(180deg, rgba(8, 11, 11, .18), transparent 24%, transparent 68%, rgba(5, 5, 4, .48));
  mix-blend-mode: screen;
}
.vignette {
  position: absolute; inset: -1px; pointer-events: none; z-index: 3;
  background:
    radial-gradient(ellipse at center, transparent 38%, rgba(2, 3, 3, .26) 64%, rgba(0, 0, 0, .84) 100%),
    linear-gradient(90deg, rgba(0,0,0,.34), transparent 18%, transparent 82%, rgba(0,0,0,.34));
}
.grain {
  position: absolute; inset: -40%; pointer-events: none; z-index: 4; opacity: .085;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 240 240' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.86' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.8'/%3E%3C/svg%3E");
  animation: grainShift .18s steps(2) infinite;
  mix-blend-mode: soft-light;
}
@keyframes grainShift {
  0% { transform: translate3d(0, 0, 0); }
  25% { transform: translate3d(-2%, 1%, 0); }
  50% { transform: translate3d(1%, -2%, 0); }
  75% { transform: translate3d(2%, 2%, 0); }
  100% { transform: translate3d(-1%, -1%, 0); }
}
.letterbox {
  position: absolute; left: 0; right: 0; height: 26px; z-index: 5; pointer-events: none;
  background: #010202; opacity: .93;
}
.letterbox.top { top: 0; }
.letterbox.bottom { bottom: 0; }

.lightning-flash, .hurt-flash, .white-fade {
  position: absolute; inset: 0; z-index: 6; pointer-events: none; opacity: 0;
}
.lightning-flash { background: #adc9dd; mix-blend-mode: screen; }
.hurt-flash { background: radial-gradient(ellipse at center, rgba(130, 10, 5, .1), rgba(95, 4, 2, .72)); }
.hurt-flash.hit { animation: hurt .55s ease-out; }
@keyframes hurt { 0% { opacity: .9; } 100% { opacity: 0; } }
.white-fade { background: #f1e8d7; transition: opacity 2s ease; z-index: 40; }
.white-fade.on { opacity: 1; }

.hidden { opacity: 0 !important; visibility: hidden !important; pointer-events: none !important; }

/* ------- loading ------- */
.loading-screen {
  position: absolute; inset: 0; z-index: 60;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  background: #030404;
  transition: opacity 1s ease, visibility 1s;
}
.loader-mark {
  font-family: var(--serif); font-size: clamp(36px, 6vw, 58px); letter-spacing: .14em;
  color: var(--bone); margin-bottom: 22px;
}
.loader-mark span { color: var(--blood); }
.loading-screen p {
  font-size: 12px; letter-spacing: .38em; color: var(--bone-dim); margin: 0 0 18px;
}
.loader-line { width: min(260px, 50vw); height: 1px; background: rgba(216,205,184,.16); overflow: hidden; }
.loader-line i { display: block; width: 40%; height: 100%; background: var(--bone); animation: load 1.4s ease-in-out infinite; }
@keyframes load { 0% { transform: translateX(-110%); } 100% { transform: translateX(350%); } }
.loading-screen small { margin-top: 20px; font-size: 9px; letter-spacing: .28em; color: rgba(216,205,184,.42); }

/* ------- screens ------- */
.screen {
  position: absolute; inset: 0; z-index: 30;
  transition: opacity .9s ease, visibility .9s;
}
.title-screen {
  display: flex; align-items: center; padding: clamp(24px, 7vw, 96px);
  background:
    linear-gradient(90deg, rgba(2,3,3,.97) 0%, rgba(2,3,3,.91) 28%, rgba(2,3,3,.38) 62%, rgba(2,3,3,.08) 100%),
    linear-gradient(0deg, rgba(2,3,3,.76), transparent 30%);
}
.title-copy { width: min(620px, 58vw); position: relative; z-index: 2; }
.eyebrow {
  display: flex; gap: 14px; align-items: center;
  margin: 0 0 22px; font-size: 11px; font-weight: 500; letter-spacing: .34em; color: var(--bone-dim);
}
.eyebrow > span { display: inline-block; width: 34px; height: 1px; background: var(--blood-bright); }
.title-copy h1 {
  font-family: var(--serif); font-weight: 400; font-size: clamp(64px, 10.2vw, 164px); line-height: .74;
  letter-spacing: -.035em; margin: 0 0 28px; color: #e6dcc7; text-shadow: 0 0 50px rgba(0,0,0,.5);
}
.title-copy h1 span { display: block; }
.title-copy h1 span:last-child { margin-left: .09em; }
.chapter {
  font-size: 12px; font-weight: 500; letter-spacing: .3em; margin: 0 0 18px; color: #b7ad9b;
}
