.title-blurb {
  margin: 0 0 38px; max-width: 390px; font-size: 16px; line-height: 1.55; font-weight: 300;
  letter-spacing: .02em; color: rgba(216,205,184,.68);
}
.title-actions { display: flex; align-items: center; gap: 22px; }
.start-btn {
  position: relative; min-width: 220px; padding: 15px 34px;
  background: rgba(216,205,184,.05); border: 1px solid rgba(216,205,184,.62);
  color: var(--bone); font-size: 14px; font-weight: 500; letter-spacing: .44em; cursor: pointer;
  transition: background .35s, border-color .35s, color .35s, letter-spacing .35s;
  backdrop-filter: blur(3px);
}
.start-btn::before {
  content: ''; position: absolute; left: -1px; top: -1px; width: 10px; height: 10px;
  border-left: 1px solid var(--blood-bright); border-top: 1px solid var(--blood-bright);
}
.start-btn:hover { background: rgba(155,47,35,.18); border-color: var(--blood-bright); letter-spacing: .5em; }
.start-caption { font-size: 10px; letter-spacing: .3em; color: rgba(216,205,184,.35); text-transform: uppercase; }
.title-warning { margin-top: 32px; max-width: 340px; font-size: 9px; line-height: 1.6; letter-spacing: .16em; color: rgba(216,205,184,.3); text-transform: uppercase; }
.title-foot {
  position: absolute; left: clamp(24px, 7vw, 96px); right: clamp(24px, 7vw, 96px); bottom: 48px;
  z-index: 2; display: flex; justify-content: space-between; align-items: center;
  font-size: 9px; font-weight: 500; letter-spacing: .24em; color: rgba(216,205,184,.34);
}
.headphones { color: rgba(216,205,184,.54); }
.title-rule { position: absolute; top: 0; bottom: 0; left: 58%; width: 1px; background: linear-gradient(180deg, transparent, rgba(216,205,184,.12), transparent); }

/* ------- HUD ------- */
.hud { position: absolute; inset: 0; z-index: 10; pointer-events: none; transition: opacity .7s; }
.hud-top-left {
  position: absolute; top: calc(42px + env(safe-area-inset-top)); left: clamp(20px, 3.5vw, 54px);
  width: min(410px, 47vw); text-shadow: 0 2px 12px #000;
}
.hud-chapter { margin: 0 0 7px; font-size: 9px; letter-spacing: .34em; color: rgba(216,205,184,.4); }
.hud-top-left h2 {
  margin: 0; font-family: var(--serif); font-size: clamp(17px, 2vw, 24px); font-weight: 400;
  letter-spacing: .12em; color: #e0d6c2;
}
.hud-top-left #objectiveSub {
  margin: 6px 0 0; font-size: 11px; line-height: 1.45; letter-spacing: .08em; color: rgba(216,205,184,.48);
  max-width: 350px;
}
.vitals { display: flex; align-items: center; gap: 9px; margin-top: 14px; width: 210px; }
.heart { font-size: 13px; color: #a94133; filter: drop-shadow(0 0 7px rgba(155,47,35,.5)); }
.vital-track { position: relative; flex: 1; height: 3px; background: rgba(255,255,255,.12); }
.vital-track i { display: block; width: 100%; height: 100%; background: linear-gradient(90deg, #7e2b20, #bb5140); transition: width .35s; }
.stamina-track { width: 40px; height: 2px; background: rgba(255,255,255,.1); }
.stamina-track i { display: block; width: 100%; height: 100%; background: rgba(216,205,184,.55); transition: width .12s linear; }

.inventory {
  position: absolute; top: calc(42px + env(safe-area-inset-top)); right: clamp(64px, 6vw, 84px);
  display: flex; gap: 8px; align-items: flex-start; justify-content: flex-end; flex-wrap: wrap; max-width: 38vw;
}
.inv-item {
  display: flex; align-items: center; gap: 7px; padding: 6px 9px;
  border: 1px solid rgba(216,205,184,.2); background: rgba(4,6,6,.42);
  font-size: 9px; letter-spacing: .15em; color: rgba(216,205,184,.75); backdrop-filter: blur(4px);
  animation: invIn .35s ease;
}
@keyframes invIn { from { transform: translateY(-6px); opacity: 0; } }
.inv-item b { font-weight: 500; color: #c8bca6; }
.inv-item .inv-icon { width: 13px; height: 13px; display: inline-flex; }
.inv-item svg { width: 100%; height: 100%; fill: none; stroke: currentColor; stroke-width: 1.4; }

.icon-btn {
  position: absolute; top: calc(38px + env(safe-area-inset-top)); right: clamp(18px, 3vw, 44px);
  width: 34px; height: 34px; border: 1px solid rgba(216,205,184,.18);
  background: rgba(4,6,6,.32); color: rgba(216,205,184,.6); font-size: 11px; cursor: pointer;
  pointer-events: auto; backdrop-filter: blur(4px);
}
.icon-btn:hover { border-color: rgba(216,205,184,.4); color: var(--bone); }

.reticle {
  position: absolute; left: 50%; top: 50%; width: 26px; height: 26px; transform: translate(-50%,-50%);
  opacity: .5; transition: opacity .2s, transform .2s;
}
.reticle i { position: absolute; left: 50%; top: 50%; width: 3px; height: 3px; border-radius: 50%; background: var(--bone); transform: translate(-50%,-50%); box-shadow: 0 0 6px #000; }
.reticle::before, .reticle::after { content: ''; position: absolute; background: rgba(216,205,184,.42); }
.reticle::before { left: 50%; top: 0; width: 1px; height: 7px; }
.reticle::after { left: 0; top: 50%; width: 7px; height: 1px; }
.reticle.active { opacity: 1; transform: translate(-50%,-50%) scale(1.25); }
.reticle.active i { background: #e2cba4; box-shadow: 0 0 12px rgba(226,203,164,.8); }

.interact-prompt {
  position: absolute; left: 50%; top: calc(50% + 42px); transform: translateX(-50%);
  display: flex; align-items: center; gap: 10px; padding: 7px 12px;
  background: rgba(3,5,4,.55); border: 1px solid rgba(216,205,184,.22); backdrop-filter: blur(4px);
  transition: opacity .2s, transform .2s;
}
.interact-prompt.hidden { display: flex !important; opacity: 0 !important; transform: translate(-50%, 4px); }
.prompt-key {
  display: none; width: 19px; height: 19px; border: 1px solid rgba(216,205,184,.5);
  align-items: center; justify-content: center; font-size: 10px; font-weight: 500;
}
body.desktop .prompt-key { display: inline-flex; }
.interact-prompt span:last-child { font-size: 10px; font-weight: 500; letter-spacing: .23em; color: #ddd2bb; }

.caption {
  position: absolute; left: 50%; bottom: calc(10.5% + env(safe-area-inset-bottom)); transform: translateX(-50%);
  width: min(640px, 76vw); text-align: center; font-family: var(--serif); font-size: clamp(15px, 1.5vw, 19px);
  line-height: 1.5; letter-spacing: .035em; color: rgba(230,221,203,.88); text-shadow: 0 2px 16px #000, 0 0 32px #000;
  opacity: 0; transition: opacity .7s;
}
.caption.show { opacity: 1; }
.caption small { display: block; margin-top: 8px; font-family: var(--cond); font-size: 9px; letter-spacing: .28em; color: rgba(216,205,184,.4); }

.ammo-hud {
  position: absolute; right: clamp(20px, 3.5vw, 52px); bottom: calc(22% + env(safe-area-inset-bottom));
  text-align: right; text-shadow: 0 2px 10px #000;
}
.ammo-hud span { font-size: 20px; font-weight: 300; letter-spacing: .14em; color: rgba(232,223,205,.92); }
.ammo-hud small { display: block; font-size: 8px; letter-spacing: .32em; color: rgba(216,205,184,.35); }
.ammo-hud.empty span { color: #b44938; }

.desktop-hint {
  position: absolute; left: 50%; bottom: calc(19px + env(safe-area-inset-bottom)); transform: translateX(-50%);
  display: flex; gap: 22px; color: rgba(216,205,184,.28); font-size: 9px; letter-spacing: .16em; white-space: nowrap;
}
.desktop-hint b { color: rgba(216,205,184,.62); font-weight: 500; }

/* ------- touch controls ------- */
.mobile-controls { display: none; }
body.touch .desktop-hint { display: none; }
body.touch .mobile-controls { display: block; }

.joystick {
  position: absolute; width: 128px; height: 128px; border-radius: 50%;
  border: 1px solid rgba(216,205,184,.17); background: radial-gradient(circle, rgba(216,205,184,.07), rgba(3,5,4,.12) 62%, transparent 66%);
  transform: translate(-50%,-50%); pointer-events: none;
}
.joy-ring { position: absolute; inset: 18px; border-radius: 50%; border: 1px solid rgba(216,205,184,.1); }
.joy-knob {
  position: absolute; left: 50%; top: 50%; width: 46px; height: 46px; border-radius: 50%;
  transform: translate(-50%,-50%); border: 1px solid rgba(216,205,184,.38);
  background: rgba(216,205,184,.1); box-shadow: 0 0 24px rgba(0,0,0,.3);
}
.round-btn {
  position: absolute; width: 58px; height: 58px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  pointer-events: auto; touch-action: none; cursor: pointer;
  border: 1px solid rgba(216,205,184,.26); background: rgba(4,7,6,.45);
  color: rgba(216,205,184,.77); backdrop-filter: blur(5px);
  transition: background .15s, border-color .15s, transform .1s, opacity .2s;
}
.round-btn:active, .round-btn.pressed { transform: scale(.94); background: rgba(155,47,35,.25); border-color: rgba(216,205,184,.6); }
.round-btn svg { width: 25px; height: 25px; fill: currentColor; }
.round-btn.disabled { opacity: .35; }
.interact-btn { width: 76px; height: 76px; right: calc(20px + env(safe-area-inset-right)); bottom: calc(42px + env(safe-area-inset-bottom)); }
.interact-btn svg { width: 31px; height: 31px; }
.fire-btn { right: calc(104px + env(safe-area-inset-right)); bottom: calc(28px + env(safe-area-inset-bottom)); width: 58px; height: 58px; }
.fire-btn span { position: absolute; right: -2px; top: -6px; font-size: 11px; color: #e2d5bd; }
.run-btn { right: calc(30px + env(safe-area-inset-right)); bottom: calc(132px + env(safe-area-inset-bottom)); width: 50px; height: 50px; }
.light-btn { right: calc(106px + env(safe-area-inset-right)); bottom: calc(106px + env(safe-area-inset-bottom)); width: 50px; height: 50px; }
.light-btn:not(.active) { color: rgba(216,205,184,.28); }
.light-btn.active { border-color: rgba(218,190,130,.56); background: rgba(105,80,35,.26); }

@media (max-width: 820px) {
  .letterbox { height: 15px; }
  .title-screen { padding: 30px 24px; align-items: flex-end; padding-bottom: 112px; }
  .title-copy { width: 100%; }
  .title-copy h1 { font-size: clamp(72px, 23vw, 120px); line-height: .72; margin-bottom: 24px; }
  .title-blurb { font-size: 14px; margin-bottom: 26px; max-width: 300px; }
  .start-btn { min-width: 190px; padding: 13px 24px; }
  .title-foot { left: 24px; right: 24px; bottom: 24px; font-size: 8px; }
  .title-foot span:first-child, .headphones { display: none; }
  .title-rule { left: auto; right: 20%; }
  .hud-top-left { top: calc(26px + env(safe-area-inset-top)); left: 18px; width: 58vw; }
  .hud-top-left h2 { font-size: 17px; }
  .hud-top-left #objectiveSub { font-size: 10px; max-width: 230px; }
  .vitals { width: 150px; }
  .inventory { top: calc(26px + env(safe-area-inset-top)); right: 54px; max-width: 34vw; gap: 4px; }
  .inv-item { padding: 4px 6px; font-size: 8px; }
  .icon-btn { top: calc(24px + env(safe-area-inset-top)); right: 14px; width: 31px; height: 31px; }
  .desktop-hint { display: none; }
  .interact-prompt { top: calc(50% + 34px); }
  .prompt-key { display: none !important; }
  .caption { bottom: calc(24% + env(safe-area-inset-bottom)); font-size: 14px; width: 82vw; }
  .ammo-hud { right: 18px; bottom: calc(36% + env(safe-area-inset-bottom)); }
  .ammo-hud span { font-size: 16px; }
  .round-btn { width: 54px; height: 54px; }
  .interact-btn { width: 72px; height: 72px; }
  .fire-btn { width: 54px; height: 54px; right: calc(98px + env(safe-area-inset-right)); bottom: calc(30px + env(safe-area-inset-bottom)); }
  .run-btn { width: 46px; height: 46px; right: calc(26px + env(safe-area-inset-right)); bottom: calc(126px + env(safe-area-inset-bottom)); }
  .light-btn { width: 46px; height: 46px; right: calc(98px + env(safe-area-inset-right)); bottom: calc(100px + env(safe-area-inset-bottom)); }
  .note-paper { width: calc(100vw - 40px); max-height: 74vh; overflow: auto; padding: 30px 26px; }
  .end-overlay h2 { font-size: 19vw; }
}
@media (max-height: 470px) and (orientation: landscape) {
  .letterbox { height: 10px; }
  .title-screen { padding: 18px 5vw; }
  .title-copy h1 { font-size: 17vh; margin-bottom: 14px; }
  .title-blurb { display: none; }
  .title-warning { display: none; }
  .title-actions { gap: 16px; }
  .eyebrow { margin-bottom: 12px; font-size: 9px; }
  .chapter { margin-bottom: 10px; font-size: 10px; }
  .title-foot { bottom: 20px; }
  .hud-top-left { top: 16px; left: 18px; }
  .hud-top-left h2 { font-size: 15px; }
  .hud-top-left #objectiveSub { display: none; }
  .vitals { margin-top: 8px; width: 130px; }
  .inventory { top: 15px; }
  .icon-btn { top: 13px; }
  .interact-btn { width: 62px; height: 62px; bottom: 18px; right: 18px; }
  .fire-btn { width: 48px; height: 48px; bottom: 20px; right: 88px; }
  .run-btn { width: 42px; height: 42px; bottom: 92px; right: 22px; }
  .light-btn { width: 42px; height: 42px; bottom: 82px; right: 84px; }
  .caption { bottom: 18%; font-size: 13px; }
  .ammo-hud { bottom: 31%; }
}

/* ------- overlays ------- */
.note-overlay {
  position: absolute; inset: 0; z-index: 35; display: flex; align-items: center; justify-content: center;
  background: rgba(1,2,2,.72); backdrop-filter: blur(5px); transition: opacity .4s, visibility .4s;
}
.note-paper {
  width: min(480px, calc(100vw - 48px)); max-height: 80vh; overflow: auto;
  padding: 42px 44px 36px; color: #2d2518;
  background:
    radial-gradient(circle at 20% 10%, rgba(120,94,50,.18), transparent 42%),
    linear-gradient(135deg, #cec19b, #b9a97f 65%, #c7b992);
  box-shadow: 0 30px 80px rgba(0,0,0,.65), inset 0 0 60px rgba(67,48,22,.22);
  transform: rotate(-.4deg);
}
.note-paper::before { content: ''; position: absolute; width: 10px; height: 80px; background: rgba(80,58,28,.1); }
.note-paper > p:first-child { margin: 0 0 14px; font-size: 9px; letter-spacing: .28em; color: rgba(45,37,24,.55); }
.note-paper h3 { margin: 0 0 20px; font-family: var(--serif); font-size: 30px; font-weight: 400; line-height: 1.05; }
.note-paper p { font-family: Georgia, serif; font-size: 22px; line-height: 1.15; letter-spacing: .015em; margin: 0 0 16px; font-style: italic; }
.note-paper button {
  margin-top: 18px; padding: 8px 0; background: none; border: 0; border-bottom: 1px solid rgba(45,37,24,.35);
  color: #2d2518; font-size: 10px; letter-spacing: .24em; cursor: pointer;
}
.pause-overlay, .end-overlay { display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; background: rgba(2,3,3,.82); backdrop-filter: blur(7px); }
.pause-overlay h2, .end-overlay h2 {
  margin: 0; font-family: var(--serif); font-weight: 400; font-size: clamp(54px, 9vw, 116px);
  letter-spacing: .04em; line-height: .95; color: #ddd2bd;
}
.pause-overlay .eyebrow, .end-overlay .eyebrow { justify-content: center; margin-bottom: 18px; }
.overlay-actions { display: flex; gap: 12px; margin-top: 38px; }
.pause-overlay button, .end-overlay button {
  padding: 13px 30px; border: 1px solid rgba(216,205,184,.3); background: rgba(216,205,184,.04);
  font-size: 11px; letter-spacing: .32em; cursor: pointer;
}
.pause-overlay button:hover, .end-overlay button:hover { border-color: var(--blood-bright); background: rgba(155,47,35,.16); }
.ghost-btn { opacity: .55; }
.end-copy { max-width: 480px; margin: 22px 0 32px; font-family: var(--serif); font-size: 17px; line-height: 1.55; color: rgba(216,205,184,.56); }
.end-tip, .end-stat { margin-top: 28px; font-size: 9px; letter-spacing: .22em; color: rgba(216,205,184,.34); }
.death-overlay { background: radial-gradient(ellipse at center, rgba(32,4,2,.65), rgba(1,1,1,.94)); }
.death-overlay h2 { color: #b04333; text-shadow: 0 0 50px rgba(155,47,35,.35); }
.win-overlay { background: radial-gradient(ellipse at center, rgba(54,51,40,.7), rgba(2,3,3,.96)); }

.toast {
  position: absolute; left: 50%; top: calc(18% + env(safe-area-inset-top)); transform: translate(-50%, -8px);
  z-index: 25; padding: 8px 16px; border: 1px solid rgba(216,205,184,.2); background: rgba(3,5,4,.65);
  font-size: 10px; letter-spacing: .24em; color: rgba(227,218,200,.88); opacity: 0; transition: opacity .35s, transform .35s;
  pointer-events: none; white-space: nowrap; backdrop-filter: blur(4px);
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }
.rotate-hint { display: none; }

/* Fallback for mouse users on narrow screens */
@media (max-width: 820px) and (pointer: fine) {
  .mobile-controls { display: block; }
  .desktop-hint { display: none; }
}

