import { createRequire } from 'node:module'
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json')
const { chromium } = require('playwright')
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--use-angle=swiftshader','--no-sandbox','--disable-dev-shm-usage'] })
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } })
const errors = []
page.on('pageerror', (e) => errors.push(e.message))
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()) })
await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.waitForFunction(() => !!window.__BLACKWATER__)
await page.click('#startBtn')
await page.waitForTimeout(900)
await page.evaluate(() => { const b = window.__BLACKWATER__; b.giveAll(); b.spawnEnemy() })
await page.waitForTimeout(500)
const before = await page.evaluate(() => {
  const b = window.__BLACKWATER__
  const e = b.world.enemy.group.position
  b.teleport(e.x, e.z - 3.0, Math.PI)
  b.player.pitch = 0.0
  return { state: b.game.state, hp: b.enemy.hp, ammo: b.game.ammo, dist: e.distanceTo(b.player.pos), camY: b.player.camY }
})
console.log('BEFORE SHOTS', before)
console.log('AIM', await page.evaluate(() => {
  const b = window.__BLACKWATER__
  const e = b.world.enemy.group.position
  const p = b.player
  const dx = e.x - p.pos.x, dz = e.z - p.pos.z, dy = (e.y + 1.35) - p.camY
  p.yaw = Math.atan2(-dx, -dz)
  p.pitch = Math.atan2(dy, Math.hypot(dx, dz))
  return { yaw: p.yaw, pitch: p.pitch }
}))
await page.waitForTimeout(800)
for (let i = 0; i < 5; i++) {
  await page.evaluate(() => window.__BLACKWATER__.fire())
  await page.waitForTimeout(700)
  console.log('SHOT', i + 1, await page.evaluate(() => {
    const b = window.__BLACKWATER__
    return { hp: b.enemy.hp, ammo: b.game.ammo, stunned: b.enemy.stunned.toFixed(2), dead: b.enemy.dead }
  }))
}
await page.screenshot({ path: 'screenshots/e2e-gun.png' })
console.log('AFTER SHOTS', await page.evaluate(() => {
  const b = window.__BLACKWATER__
  return { hp: b.enemy.hp, dead: b.enemy.dead, gameDead: b.game.enemyDead, ammo: b.game.ammo, state: b.game.state }
}))
console.log('ERRORS', errors)
await browser.close()

