import { createRequire } from 'node:module'
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json')
const { chromium, devices } = require('playwright')
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--use-angle=swiftshader','--no-sandbox','--disable-dev-shm-usage'] })
const context = await browser.newContext({ ...devices['iPhone 13'] })
const page = await context.newPage()
const errors = []
page.on('pageerror', (e) => errors.push(e.message))
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()) })
await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.waitForFunction(() => !!window.__BLACKWATER__)
await page.waitForTimeout(600)
console.log('VIEWPORT', page.viewportSize(), 'touch class', await page.evaluate(() => document.body.className))
await page.screenshot({ path: 'screenshots/m-title-new.png' })
await page.tap('#startBtn')
await page.waitForTimeout(1800)
await page.screenshot({ path: 'screenshots/m-game-idle.png' })

const boxes = await page.evaluate(() => {
  const ids = ['runBtn','lightBtn','fireBtn','interactBtn','moveHint','pauseBtn','inventory','joystick']
  const out = {}
  for (const id of ids) {
    const el = document.getElementById(id)
    if (!el) continue
    const r = el.getBoundingClientRect()
    const cs = getComputedStyle(el)
    out[id] = { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), display: cs.display, opacity: cs.opacity, cls: el.className }
  }
  return out
})
console.log('BOXES', boxes)

const cdp = await context.newCDPSession(page)
const touch = (type, x, y) => cdp.send('Input.dispatchTouchEvent', { type, touchPoints: type === 'touchEnd' ? [] : [{ x, y, id: 1, radiusX: 8, radiusY: 8 }] })
const before = await page.evaluate(() => { const b = window.__BLACKWATER__; return { x: b.player.pos.x, z: b.player.pos.z, yaw: b.player.yaw } })
await touch('touchStart', 82, 690)
await page.waitForTimeout(120)
await touch('touchMove', 124, 650)
await page.waitForTimeout(2500)
await page.screenshot({ path: 'screenshots/m-joystick.png' })
const during = await page.evaluate(() => {
  const b = window.__BLACKWATER__
  const j = document.getElementById('joystick')
  const r = j.getBoundingClientRect()
  return { x: b.player.pos.x, z: b.player.pos.z, yaw: b.player.yaw, joy: { x: r.x, y: r.y, w: r.width, h: r.height, hidden: j.classList.contains('hidden'), left: j.style.left, top: j.style.top }, hintHidden: document.getElementById('moveHint').classList.contains('hidden'), joyKnob: document.querySelector('.joy-knob').style.transform }
})
await touch('touchEnd', 124, 650)
console.log('MOVE BEFORE', before)
console.log('MOVE DURING', during)
await page.waitForTimeout(600)
console.log('AFTER RELEASE', await page.evaluate(() => ({ yaw: window.__BLACKWATER__.player.yaw, joyHidden: document.getElementById('joystick').classList.contains('hidden'), hintHidden: document.getElementById('moveHint').classList.contains('hidden') })))

// look drag on right side
const yaw0 = await page.evaluate(() => window.__BLACKWATER__.player.yaw)
await touch('touchStart', 300, 430)
await page.waitForTimeout(100)
await touch('touchMove', 210, 430)
await page.waitForTimeout(900)
await touch('touchEnd', 210, 430)
const yaw1 = await page.evaluate(() => window.__BLACKWATER__.player.yaw)
console.log('LOOK YAW', yaw0, '->', yaw1)

// inventory + gun layout
await page.evaluate(() => { const b = window.__BLACKWATER__; b.giveAll(); const item = b.world.interactables.find(i => i.id === 'gun'); item.enabled = false; item.object.visible = false })
await page.waitForTimeout(1200)
await page.screenshot({ path: 'screenshots/m-inventory-gun.png' })
console.log('INVENTORY', await page.evaluate(() => {
  const inv = document.getElementById('inventory')
  const pause = document.getElementById('pauseBtn')
  const a = inv.getBoundingClientRect(), b = pause.getBoundingClientRect()
  return { inv: [a.x,a.y,a.width,a.height], pause: [b.x,b.y,b.width,b.height], fireHidden: document.getElementById('fireBtn').classList.contains('hidden'), ammo: document.getElementById('ammoCount').textContent }
}))
console.log('ERRORS', errors)
await browser.close()

