import { createRequire } from 'node:module'
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json')
const { chromium, devices } = require('playwright')
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--use-angle=swiftshader','--no-sandbox'] })
const context = await browser.newContext({ ...devices['iPhone 13'] })
const page = await context.newPage()
await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.waitForFunction(() => !!window.__BLACKWATER__)
await page.tap('#startBtn')
await page.waitForTimeout(1500)
console.log(await page.evaluate(() => {
  const el = document.elementFromPoint(100, 560)
  return { tag: el?.tagName, id: el?.id, cls: el?.className, w: innerWidth, h: innerHeight, dpr: devicePixelRatio }
}))
await page.evaluate(() => {
  window.__ev = []
  const c = document.getElementById('scene')
  for (const t of ['pointerdown','pointermove','pointerup','touchstart','touchmove','touchend']) {
    c.addEventListener(t, (e) => window.__ev.push({ t, pt: e.pointerType, x: e.clientX, y: e.clientY, touches: e.touches?.length, id: e.pointerId }), { passive: false })
  }
})
const cdp = await context.newCDPSession(page)
const touch = (type, x, y) => cdp.send('Input.dispatchTouchEvent', { type, touchPoints: type === 'touchEnd' ? [] : [{ x, y, id: 1, radiusX: 8, radiusY: 8, force: 1 }] })
await touch('touchStart', 100, 560)
await page.waitForTimeout(400)
console.log('AFTER START', await page.evaluate(() => ({ ev: window.__ev, joy: document.getElementById('joystick').className, left: document.getElementById('joystick').style.left, top: document.getElementById('joystick').style.top, joyBox: document.getElementById('joystick').getBoundingClientRect().toJSON() })))
await touch('touchMove', 150, 520)
await page.waitForTimeout(600)
console.log('AFTER MOVE', await page.evaluate(() => ({ ev: window.__ev, joy: document.getElementById('joystick').className, left: document.getElementById('joystick').style.left, top: document.getElementById('joystick').style.top, joyBox: document.getElementById('joystick').getBoundingClientRect().toJSON(), hint: document.getElementById('moveHint').className })))
await touch('touchEnd', 150, 520)
await page.waitForTimeout(400)
console.log('END', await page.evaluate(() => ({ ev: window.__ev, joy: document.getElementById('joystick').className })))
await browser.close()

