import { createRequire } from 'node:module'
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json')
const { chromium } = require('playwright')
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--use-angle=swiftshader','--no-sandbox'] })
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } })
const errors = []
page.on('pageerror', (e) => errors.push(e.message))
await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.waitForFunction(() => !!window.__BLACKWATER__)
await page.click('#startBtn')
await page.waitForTimeout(800)
await page.evaluate(() => {
  const b = window.__BLACKWATER__
  b.game.hasKey = true
  b.teleport(0, 7.35)
  const item = b.world.interactables.find(i => i.id === 'frontDoor')
  const v = b.camera.position.clone(); item.object.getWorldPosition(v)
  const p = b.player
  p.yaw = Math.atan2(-(v.x - p.pos.x), -(v.z - p.pos.z))
  p.pitch = Math.atan2(v.y - p.camY, Math.hypot(v.x - p.pos.x, v.z - p.pos.z))
})
await page.waitForTimeout(1000)
await page.evaluate(() => window.__BLACKWATER__.interact())
await page.waitForTimeout(2200)
await page.screenshot({ path: 'screenshots/v-win2.png' })
console.log(await page.evaluate(() => {
  const w = document.getElementById('whiteFade')
  return { state: window.__BLACKWATER__.game.state, whiteOpacity: getComputedStyle(w).opacity, whiteAnim: getComputedStyle(w).animationName, winVisible: !document.getElementById('winOverlay').classList.contains('hidden'), winZ: getComputedStyle(document.getElementById('winOverlay')).zIndex }
}))
console.log('ERRORS', errors)
await browser.close()

