const page = await browser.newPage({ viewport: { width: 900, height: 600 } })
await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.waitForFunction(() => !!window.__BLACKWATER__)
const res = await page.evaluate(() => {
  const b = window.__BLACKWATER__
  const V = b.camera.position.constructor
  const nav = b.nav
  const navIndex = (x, z) => {
    const col = Math.max(0, Math.min(nav.cols - 1, Math.round((x - nav.minX) / nav.cell)))
    const row = Math.max(0, Math.min(nav.rows - 1, Math.round((z - nav.minZ) / nav.cell)))
    return row * nav.cols + col
  }
  const candidates = [
    [-5.6,-2.3],[-5.6,-4.9],[-6.2,-5.3],[-5.0,-3.0],
    [5.6,-3.8],[6.2,-4.5],[7.0,-2.0],[5.0,-4.5],
    [-5.0,5.8],[-4.2,3.5],[-6.8,5.8],[-5.0,3.6],
    [5.8,3.5],[7.6,3.8],[4.6,3.6],[7.9,5.9],
  ]
  return candidates.map(([x,z]) => {
    const idx = navIndex(x,z)
    const p = b.findPath(new V(0,0,8.2), new V(x,0,z))
    const last = p.length ? p[p.length-1] : null
    return { x, z, blocked: nav.blocked[idx], len: p.length, endDist: last ? Math.hypot(last.x-x,last.z-z).toFixed(2) : null }
  })
})
